CREATE COLUMN TABLE "GC_COPLAIM"."QBOB" (
   "ID_QBOB" INTEGER PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
   "IDBOB" NVARCHAR(100) NOT NULL,
   "ITEMCODE" NVARCHAR(100) NOT NULL,
   "LOTE" NVARCHAR(100) NOT NULL,
   "ALMACEN" NVARCHAR(100) NOT NULL,
   "GRAMAJE" DECIMAL(21,6) NOT NULL,
   "ANCHO" DECIMAL(21,6) NOT NULL,
   "STOCK" DECIMAL(21,6) NOT NULL,
   "CREATED_AT" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
   "UPDATED_AT" TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE COLUMN TABLE "GC_COPLAIM"."COCA" (
   "ID_TINTA" NVARCHAR(50) CS_STRING PRIMARY KEY,
   "TINTA" NVARCHAR(100) CS_STRING NOT NULL,
   "USER" NVARCHAR(100) CS_STRING NOT NULL,
   "CREATED_AT" LONGDATE CS_LONGDATE NOT NULL,
   "UPDATED_AT" LONGDATE CS_LONGDATE NOT NULL
);

CREATE COLUMN TABLE "GC_COPLAIM"."TICA" (
   "ID_TICA" INTEGER PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
   "OC" NVARCHAR(100) CS_STRING NOT NULL,
   "PROVEEDOR" NVARCHAR(50) CS_STRING NOT NULL,
   "RESPONSABLE" INTEGER CS_INT NOT NULL,
   "TIEMPO" LONGDATE CS_LONGDATE NOT NULL,
   "MONTACARGA" INTEGER CS_INT NOT NULL,
   "OBSERVACIONES" NVARCHAR(750) CS_STRING,
   "ANALISTA" NVARCHAR(50) CS_STRING NOT NULL,
   "ESTADO" NVARCHAR(50) CS_STRING DEFAULT 'A',
   "CREATED_AT" LONGDATE CS_LONGDATE NOT NULL,
   "UPDATED_AT" LONGDATE CS_LONGDATE NOT NULL
);

CREATE COLUMN TABLE "GC_COPLAIM"."DOTI" (
   "ID_DOTI" INTEGER PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
   "ID_TICA" INTEGER CS_INT NOT NULL,
   "ID_TINTA" NVARCHAR(50) CS_STRING NOT NULL,
   "LOTE" NVARCHAR(100) CS_STRING NOT NULL,
   "CANTIDAD" INTEGER CS_INT NOT NULL,
   "TONALIDAD" NVARCHAR(150) CS_STRING NOT NULL,
   "VISCOSIDAD" DECIMAL(10,2) CS_FIXED NOT NULL,
   "PH" DECIMAL(10,2) CS_FIXED NOT NULL,
   "ESPECTROFOTOMETRO" DECIMAL(10,2) CS_FIXED NOT NULL,
   "RESISTENCIA" NVARCHAR(100) CS_STRING NOT NULL,
   "SUSTRATO" NVARCHAR(50) CS_STRING NOT NULL,
   "ESTADO" NVARCHAR(50) CS_STRING DEFAULT 'Y',
   "OBSERVACIONES" NVARCHAR(750) CS_STRING,
   "ANALISTA" NVARCHAR(50) CS_STRING NOT NULL,
   "CREATED_AT" LONGDATE CS_LONGDATE NOT NULL,
   "UPDATED_AT" LONGDATE CS_LONGDATE NOT NULL
);

ALTER TABLE "GC_COPLAIM"."DOTI" ADD CONSTRAINT "DOTI_FK_ID_TICA" FOREIGN KEY ("ID_TICA") REFERENCES "GC_COPLAIM"."TICA" ("ID_TICA") ON
UPDATE
   RESTRICT ON
   DELETE
   RESTRICT;

