CREATE COLUMN TABLE "GC_COPLAIM"."CPCA" (
   "ID_CPCA" INTEGER GENERATED BY DEFAULT AS IDENTITY,
   "ORDEN_PROD" INTEGER CS_INT PRIMARY KEY,
   "LOTE_SAP" NVARCHAR(100) CS_STRING,
   "LOTE_CAL" NVARCHAR(100) CS_STRING,
   "ORDEN_COMP" NVARCHAR(100) CS_STRING,
   "ORDEN_VENT" INTEGER CS_INT,
   "PT_CODE" NVARCHAR(50) CS_STRING NOT NULL,
   "ECT_STD" DECIMAL(10,2) CS_FIXED,
   "ANALISTA" NVARCHAR(50) CS_STRING NOT NULL,
   "TIEMPO" LONGDATE CS_LONGDATE NOT NULL,
   "ESTADO" NVARCHAR(100) CS_STRING DEFAULT 'LIBERADO',
   "OBSERVACIONES" NVARCHAR(750) CS_STRING,
   "STATUS" NVARCHAR(10) DEFAULT 'Y',
   "CREATED_AT" LONGDATE CS_LONGDATE NOT NULL,
   "UPDATED_AT" LONGDATE CS_LONGDATE NOT NULL
);

CREATE COLUMN TABLE "GC_COPLAIM"."DOCP" (
   "ID_DOCP" INTEGER PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
   "ORDEN_PROD" INTEGER CS_INT NOT NULL,
   "ECT" DECIMAL(10,3) CS_FIXED NOT NULL,
   "CALIBRE_MM" INTEGER CS_INT NOT NULL,
   "CALIBRE_IN" DECIMAL(10,3) CS_FIXED,
   "PAT_B" DECIMAL(10,3) CS_FIXED NOT NULL,
   "PAT_C" DECIMAL(10,3) CS_FIXED NOT NULL,
   "FCTC" DECIMAL(10,3) CS_FIXED NOT NULL,
   "GRAMAJE" INTEGER CS_INT NOT NULL,
   "COBB" INTEGER CS_INT NOT NULL,
   "BCT_TEO" DECIMAL(10,3) CS_FIXED,
   "BCTRE_ONE" INTEGER CS_INT NOT NULL,
   "BCTRE_TWO" INTEGER CS_INT NOT NULL,
   "BCTRE_TREE" INTEGER CS_INT NOT NULL,
   "BCTREPRO_LBF" DECIMAL(10,3) CS_FIXED,
   "CARGA_EST" DECIMAL(10,3) CS_FIXED,
   "LARGO" INTEGER CS_INT NOT NULL,
   "ANCHO" INTEGER CS_INT NOT NULL,
   "ALTO" INTEGER CS_INT NOT NULL,
   "PERIMETRO" DECIMAL(10,3) CS_FIXED,
   "UNI_BULTO" INTEGER CS_INT NOT NULL,
   "CHECK_CIMP" BOOLEAN CS_INT DEFAULT FALSE,
   "CHECK_PAL" BOOLEAN CS_INT DEFAULT FALSE,
   "CHECK_RECINT" BOOLEAN CS_INT DEFAULT FALSE,
   "CHECK_IMPTXT" BOOLEAN CS_INT DEFAULT FALSE,
   "CHECK_IMPIMG" BOOLEAN CS_INT DEFAULT FALSE,
   "CHECK_IMPCOD" BOOLEAN CS_INT DEFAULT FALSE,
   "REQUERIMIENTO" NVARCHAR(750) CS_STRING,
   "OBSERVACIONES" NVARCHAR(750) CS_STRING,
   "ANALISTA" NVARCHAR(50) CS_STRING NOT NULL,
   "HUMEDAD" DECIMAL(10, 3) CS_FIXED NOT NULL,
   "CREATED_AT" LONGDATE CS_LONGDATE NOT NULL,
   "UPDATED_AT" LONGDATE CS_LONGDATE NOT NULL
);

ALTER TABLE "GC_COPLAIM"."DOCP" ADD CONSTRAINT "DOCP_FK_OP_CPCA" FOREIGN KEY ("ORDEN_PROD") REFERENCES "GC_COPLAIM"."CPCA" ("ORDEN_PROD") ON
UPDATE
   RESTRICT ON
   DELETE
   RESTRICT;

CREATE COLUMN TABLE "GC_COPLAIM"."PLPT" (
   "ID_PLPT" INTEGER PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
