   "UPDATED_AT" LONGDATE CS_LONGDATE NOT NULL
);

CREATE COLUMN TABLE "GC_COPLAIM"."HSPL" (
   "ID_HSPL" INTEGER PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
   "ACCION" NVARCHAR(50) CS_STRING NOT NULL,
   "USER" NVARCHAR(50) CS_STRING NOT NULL,
   "CREATED_AT" LONGDATE CS_LONGDATE NOT NULL,
   "UPDATED_AT" LONGDATE CS_LONGDATE NOT NULL
);

CREATE COLUMN TABLE "GC_COPLAIM"."PDFCA" (
   "ID_PDFCA" INTEGER PRIMARY KEY,
   "GUIA" NVARCHAR(100) NOT NULL,
   "DOC_SAP" NVARCHAR(100) NOT NULL,
